{
  "decisions": [
    {
      "surface": "effective date of subsidiary status",
      "action": "create",
      "measure": "effective date of subsidiary status",
      "description": "The date on which an entity becomes a subsidiary."
    },
    {
      "surface": "fair value of identifiable assets",
      "action": "create",
      "measure": "fair value of identifiable assets",
      "description": "The fair value of assets identified during an acquisition."
    },
    {
      "surface": "total fair value of assets acquired",
      "action": "create",
      "measure": "total fair value of assets acquired",
      "description": "The aggregate fair value of all assets acquired in a transaction."
    },
    {
      "surface": "fair value of liabilities assumed",
      "action": "create",
      "measure": "fair value of liabilities assumed",
      "description": "The fair value of specific liabilities assumed during an acquisition."
    },
    {
      "surface": "total fair value of liabilities assumed",
      "action": "create",
      "measure": "total fair value of liabilities assumed",
      "description": "The aggregate fair value of all liabilities assumed in a transaction."
    },
    {
      "surface": "identifiable net asset at fair value",
      "action": "create",
      "measure": "identifiable net asset at fair value",
      "description": "The net value of identifiable assets minus liabilities at fair value."
    },
    {
      "surface": "contribution to revenue",
      "action": "create",
      "measure": "contribution to revenue",
      "description": "Revenue generated by an acquired entity post-acquisition."
    },
    {
      "surface": "contribution to loss before tax",
      "action": "create",
      "measure": "contribution to loss before tax",
      "description": "Loss generated by an acquired entity post-acquisition."
    },
    {
      "surface": "net cash used in acquisition",
      "action": "create",
      "measure": "net cash used in acquisition",
      "description": "The net cash outflow for an acquisition transaction."
    },
    {
      "surface": "filing date with registrar of companies",
      "action": "create",
      "measure": "filing date with registrar of companies",
      "description": "The date a document is filed with the ROC."
    },
    {
      "surface": "investment consideration",
      "action": "create",
      "measure": "investment consideration",
      "description": "The amount paid or payable for an investment."
    },
    {
      "surface": "additional stake acquisition consideration",
      "action": "create",
      "measure": "additional stake acquisition consideration",
      "description": "The amount paid for an additional equity stake."
    },
    {
      "surface": "carrying value",
      "action": "create",
      "measure": "carrying value",
      "description": "The value at which an asset or liability is carried on the balance sheet."
    },
    {
      "surface": "fair value",
      "action": "create",
      "measure": "fair value",
      "description": "The price that would be received to sell an asset or paid to transfer a liability."
    },
    {
      "surface": "addition during the year",
      "action": "create",
      "measure": "addition during the year",
      "description": "The value of additions to an asset class during the reporting period."
    },
    {
      "surface": "percentage of net sales",
      "action": "create",
      "measure": "percentage of net sales",
      "description": "A ratio representing a portion of total net sales."
    },
    {
      "surface": "number of options exercisable at the end of the year",
      "action": "create",
      "measure": "number of options exercisable at the end of the year",
      "description": "The count of stock options that can be exercised at year-end."
    },
    {
      "surface": "number of options granted during the year",
      "action": "create",
      "measure": "number of options granted during the year",
      "description": "The count of stock options granted during the reporting period."
    },
    {
      "surface": "number of options exercised during the year",
      "action": "create",
      "measure": "number of options exercised during the year",
      "description": "The count of stock options exercised during the reporting period."
    },
    {
      "surface": "revenue from operations",
      "action": "link",
      "measure": "revenue from contract with customers",
      "description": "Revenue from operations is synonymous with revenue from contracts with customers."
    },
    {
      "surface": "non - current operating assets",
      "action": "create",
      "measure": "non-current operating assets",
      "description": "Long-term assets used in the operation of the business."
    },
    {
      "surface": "investment",
      "action": "link",
      "measure": "investment in equity",
      "description": "Investment in an entity is typically an investment in equity."
    },
    {
      "surface": "consideration for additional stake",
      "action": "link",
      "measure": "additional stake acquisition consideration",
      "description": "These refer to the same financial consideration for increasing equity ownership."
    },
    {
      "surface": "cash and cash equivalents",
      "action": "create",
      "measure": "cash and cash equivalents",
      "description": "Highly liquid assets held by the company."
    }
  ]
}
